function compress(text) {
  let out = '';
  let i = 0;
  while (i < text.length) {
    let j = i;
    while (j < text.length && text[j] === text[i]) j += 1;
    out += text[i] + (j - i > 1 ? String(j - i) : '');
    i = j;
  }
  return out;
}

