def length_of_longest_substring(text):
    last = {}
    start = 0
    best = 0
    for i, ch in enumerate(text):
        if ch in last and last[ch] >= start:
            start = last[ch] + 1
        last[ch] = i
        best = max(best, i - start + 1)
    return best

template.javascript:
function lengthOfLongestSubstring(text) {
  const last = new Map();
  let start = 0;
  let best = 0;
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    if (last.has(ch) && last.get(ch) >= start) start = last.get(ch) + 1;
    last.set(ch, i);
    best = Math.max(best, i - start + 1);
  }
  return best;
}
